public class BitInputStream_readBits_TriageGen2Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this value based on context





    @Test
    public void testReadBits_LittleEndian_Simple() throws IOException {
        // 0x01 -> 00000001
        byte[] data = {0x01};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 4 bits: should be 1
        assertEquals(1L, bis.readBits(4));
        // Read 4 bits: should be 0
        assertEquals(0L, bis.readBits(4));
    }
















}

